do $$ begin if not exists(select 1 from cron.job where jobname='datasub-reconcile-2m') then perform cron.schedule('datasub-reconcile-2m','*/2 * * * *',$cmd$select net.http_post(url:=(select decrypted_secret from vault.decrypted_secrets where name='datasub_project_url')||'/functions/v1/datasub-reconcile',headers:=jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||(select decrypted_secret from vault.decrypted_secrets where name='datasub_publishable_key')),body:='{}'::jsonb);$cmd$); end if; end $$;